readonly struct RandomAccessTag { }
readonly struct ForwardTag { }

static int At(int[] a, int i, RandomAccessTag _) => a[i];          // O(1)
static int At(IEnumerable<int> a, int i, ForwardTag _) => a.Skip(i).First();   // O(n)

// call site: chosen by overload resolution, the tag struct is a compile-time marker
// At(a, 3, new RandomAccessTag());

// generic code cannot rank on T; it constrains it instead (C# 11):
static T Add<T>(T l, T r) where T : INumber<T> => l + r;
